import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import {stageFrontend} from './stage-dev-runtime.mjs';
const front=stageFrontend(fs.readFileSync(new URL('../../ms.js',import.meta.url),'utf8'));
const names=['pnoV18TextValue','pnoV18UniqueValues','pnoV18FilterOption','pnoV18ValidateFilter','pnoV18DisplayBranch','pnoV18TypeLabel','pnoV18ParcelStatus','pnoV18ParcelAction','pnoV18ParcelFilterActive','pnoV18ParcelFilterDataset','pnoV18FilteredParcelEntries','pnoV18BagGroups','pnoV18BagValue','pnoV18BagLatest','pnoV18BagSummary','pnoV18FilteredBagGroups','pnoV18FilterSummaryText','pnoV18RenderFilters','pnoV18RenderBags','pnoV18RenderBagSummary','pnoV18HasActiveFilters','pnoV18LoadBags','pnoV18TsvCell','pnoV18LineCell','pnoV18AppendLineLimited','pnoV18Copy','pnoV18CopyLine','pnoV18Export'];
export function extract(source,name){const p=source.indexOf(`function ${name}(`),a=source.slice(p-6,p)==='async '?p-6:p,b=source.indexOf('\n}\n',p)+2;assert.ok(p>=0&&b>p,name);return source.slice(a,b);}
const item=(pno,bag,hub,branch,status='รอ',action='SEAL')=>({pno,backingNo:bag,targetHub:hub,targetBranch:branch,nextStoreName:'NEXT_ONLY',status,lastAction:action,lastActionAt:'2026-10-13T02:00:01.125Z'});
const fixture=[item('P1','B1','NE11','(TH1) สาขา ก'),item('P2','B1','E1','สาขา ข','เข้าแล้ว','SHIPMENT_WAREHOUSE_SCAN'),item('P3','B2','E1','สาขา ข'),item('P4','B3','',''),item('P5','','NE11','สาขา ก')];
export function harness(rows=fixture,source=front){
 const nodes=new Map(),obs={fetch:[],clip:'',exports:[],cache:0};const node=k=>{if(!nodes.has(k))nodes.set(k,{innerHTML:'',textContent:'',classList:{add(){},remove(){},toggle(){}},querySelectorAll(){return [...this.innerHTML.matchAll(/data-pno-v18-filter="([^"]+)"([^>]*)>/g)].map(m=>({dataset:{pnoV18Filter:m[1]},value:'',disabled:/disabled/.test(m[2])}));}});return nodes.get(k);};
 const state={type:'bag',filters:{status:'',action:'',hub:'',branch:''},bagRows:rows,total:rows.length,expandedBag:'',sourceRow:{proofId:'SYNTH-P',hub:'NE11',pnoSourceDay:'2026-10-13',pnoLineId:'L1'},force:false,busy:false};
 const context=vm.createContext({pnoV18State:state,el:node,esc:v=>String(v??''),nf:new Intl.NumberFormat('en-US'),Date,console,pendingParcelRows:[],pnoV18SourceRow:()=>state.sourceRow,pnoV18LocatorKey:r=>JSON.stringify(r),pnoV18ViewCache:new Map(),pnoV18BagCache:new Map(),pnoV18CacheGet:()=>null,pnoV18CacheSet:()=>{obs.cache++},pnoInboundToggleActions(){},pnoPendingRenderNote(){},pnoV18SetActive(){},pnoV18RenderCurrentFilteredView(){},pnoV18RenderSummary(){},pnoV18UpdateFilterResult(){},pnoV18LineHeader:()=>['HEADER'],pnoV18WriteClipboard:async t=>{obs.clip=t;return true},toast(){},pnoV18Fetch:async(_t,p)=>{obs.fetch.push(p);return {page:p,total:rows.length,sourceValid:true,parcels:rows.slice((p-1)*200,p*200)}},XLSX:{utils:{json_to_sheet:v=>{obs.exports=v;return v},book_new:()=>({}),book_append_sheet(){}},writeFile(){}}});
 vm.runInContext(names.map(n=>extract(source,n)).join('\n'),context);
 return {state,nodes,obs,context,call:s=>vm.runInContext(s,context),node};
}
test('ordinary bag and unfiltered unique totals preserve member cardinality',()=>{const h=harness();assert.equal(h.call('pnoV18FilteredBagGroups().length'),3);assert.equal(h.call('pnoV18FilteredBagGroups().reduce((s,[,r])=>s+r.length,0)'),4);});
test('mixed HUB same bag filters members before grouping',()=>{const h=harness();h.state.filters.hub='NE11';assert.deepEqual(JSON.parse(JSON.stringify(h.call('pnoV18FilteredBagGroups()'))).map(([b,r])=>[b,r.map(x=>x.pno)]),[['B1',['P1']]]);});
test('mixed branch same bag exact raw R field never next store',()=>{const h=harness();h.state.filters.branch='สาขา ข';assert.equal(h.call('pnoV18FilteredBagGroups().reduce((s,[,r])=>s+r.length,0)'),2);h.state.filters.branch='NEXT_ONLY';assert.equal(h.call('pnoV18FilteredBagGroups().length'),0);});
test('mixed status action uses same parcel projection as ALL',()=>{const h=harness();h.state.filters.action='ปิดผนึก';h.state.filters.status='รอ';assert.equal(h.call('pnoV18FilteredBagGroups().reduce((s,[,r])=>s+r.length,0)'),3);assert.equal(h.call('pnoV18ParcelFilterActive()'),true);});
test('four selectors, HUB-conditioned branches, persistent global options',()=>{const h=harness();h.call('pnoV18RenderFilters()');let html=h.node('pno-v18-filterbar').innerHTML;for(const field of ['status','action','hub','branch'])assert.ok(html.includes(`data-pno-v18-filter="${field}"`));h.state.filters.hub='NE11';h.state.filters.branch='สาขา ข';h.state.filters.status='ไม่มีผล';h.call('pnoV18RenderFilters()');assert.equal(h.state.filters.branch,'');assert.equal(h.state.filters.status,'ไม่มีผล');html=h.node('pno-v18-filterbar').innerHTML;assert.ok(html.includes('E1'));assert.ok(html.includes('value="(TH1) สาขา ก"'));assert.ok(!html.includes('ชื่อสาขาต่อไป'));});
test('HUB alone active and truthful filter summary',()=>{const h=harness();h.state.filters.hub='E1';assert.equal(h.call('pnoV18ParcelFilterActive()'),true);assert.ok(h.call('pnoV18FilterSummaryText()').includes('HUB ปลายทาง=E1'));});
test('desktop mobile expanded membership equals filtered parcel set',()=>{const h=harness();h.state.filters.hub='NE11';h.state.expandedBag='B1';h.call('pnoV18RenderBags(pnoV18State.bagRows)');const html=h.node('pending-parcels-list').innerHTML;assert.ok(html.includes('P1'));assert.ok(!html.includes('P2'));assert.ok(html.includes('pno-v18-desktop')&&html.includes('pno-v18-mobile'));assert.ok(html.includes('HUB ปลายทาง'));});
test('clipboard LINE XLSX contain no unmatched member or destination',async()=>{const h=harness();h.state.filters.hub='NE11';h.state.expandedBag='B1';await h.call('pnoV18Copy()');assert.ok(h.obs.clip.includes('P1')&&!h.obs.clip.includes('P2'));await h.call('pnoV18CopyLine()');assert.ok(h.obs.clip.includes('P1')&&!h.obs.clip.includes('P2'));await h.call('pnoV18Export()');assert.equal(h.obs.exports.length,1);assert.equal(h.obs.exports[0]['จำนวนพัสดุ'],1);assert.equal(h.obs.exports[0]['HUB ปลายทาง'],'NE11');assert.equal(h.obs.exports[0]['ชื่อสาขาต่อไป'],'NEXT_ONLY');assert.equal(h.obs.fetch.length,0);});
test('unknown destination stays unknown without fallback',()=>{const h=harness([item('U','BU','','')]);assert.equal(h.call('pnoV18BagSummary(pnoV18State.bagRows).hub'),'-');assert.equal(h.call('pnoV18BagSummary(pnoV18State.bagRows).branch'),'-');h.state.filters.hub='NE11';assert.equal(h.call('pnoV18FilteredBagGroups().length'),0);});
test('duplicate PNO pages fail closed, never silently collapse counts',()=>{const h=harness([fixture[0],{...fixture[0]}]);assert.throws(()=>h.call('pnoV18FilteredBagGroups()'),/ซ้ำ/);});
test('same PNO in different opened occurrences stays separately scoped',()=>{const a=harness([fixture[0]]),b=harness([{...fixture[0],targetHub:'E1'}]);a.state.filters.hub='NE11';b.state.filters.hub='E1';assert.equal(a.call('pnoV18FilteredBagGroups().length'),1);assert.equal(b.call('pnoV18FilteredBagGroups().length'),1);});
test('22 pages complete input uses baseline number of fetch calls',async()=>{const rows=Array.from({length:4205},(_,i)=>item('P'+i,'B'+Math.floor(i/10),i%2?'NE11':'E1','R'+i%3));const h=harness(rows);h.state.bagRows=null;await h.call('pnoV18LoadBags()');assert.equal(h.obs.fetch.length,22);assert.equal(h.state.bagRows.length,4205);assert.equal(h.obs.cache,1);assert.equal(h.state.filterError,'');});
test('incomplete page never enters cache or successful totals',async()=>{const h=harness(Array.from({length:201},(_,i)=>item('P'+i,'B1','NE11','R')));const all=h.state.bagRows;h.context.pnoV18Fetch=async(_t,p)=>({total:201,page:p,parcels:p===1?all.slice(0,200):[]});await h.call('pnoV18LoadBags()');assert.equal(h.state.bagRows,null);assert.equal(h.obs.cache,0);assert.ok(h.state.filterError);});
test('cache reopen does not refetch and preserves selected filters',async()=>{const h=harness();h.context.pnoV18CacheGet=()=>({rows:fixture,total:fixture.length});h.state.filters.hub='E1';await h.call('pnoV18LoadBags()');assert.equal(h.obs.fetch.length,0);assert.equal(h.state.filters.hub,'E1');assert.equal(h.call('pnoV18FilteredBagGroups().length'),2);});
test('zero match preserves option sources and no new transport',()=>{const h=harness();h.state.filters.action='ไม่ตรง';h.call('pnoV18RenderFilters()');assert.equal(h.call('pnoV18FilteredBagGroups().length'),0);assert.ok(h.node('pno-v18-filterbar').innerHTML.includes('E1'));assert.equal(h.obs.fetch.length,0);});
test('patch is idempotent and has no request or timer in new filter projection',()=>{assert.equal(stageFrontend(front),front);new Function(front);for(const n of ['pnoV18FilteredBagGroups','pnoV18RenderFilters'])assert.doesNotMatch(extract(front,n),/fetch\s*\(|setInterval|setTimeout|apiGet/);});
